import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';

/**
 * Where uploaded files live. The local adapter suits one server and
 * development; an object-storage adapter (S3, R2) replaces it without
 * touching callers.
 */
export interface MediaStorage {
  put(key: string, data: Buffer): Promise<void>;
  delete(key: string): Promise<void>;
  /** The address clients load the file from. May be relative to the API origin. */
  urlFor(key: string): string;
}

export const MEDIA_STORAGE = Symbol('MEDIA_STORAGE');

/** Keys are generated by us, never taken from a client, but check anyway. */
const SAFE_KEY = /^[a-z0-9][a-z0-9/_-]*\.[a-z0-9]{2,5}$/;

export class LocalDiskMediaStorage implements MediaStorage {
  private readonly root: string;

  constructor(
    dir: string,
    private readonly publicBaseUrl: string | undefined,
  ) {
    this.root = resolve(dir);
  }

  async put(key: string, data: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, data, { flag: 'wx' });
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }

  urlFor(key: string): string {
    return `${this.publicBaseUrl ?? '/media'}/${key}`;
  }

  private pathFor(key: string): string {
    if (!SAFE_KEY.test(key) || key.includes('..')) {
      throw new Error(`Refusing unsafe media key "${key}"`);
    }
    return join(this.root, key);
  }
}
